package com.fasterxml.jackson.core;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser.NumberType;
import com.fasterxml.jackson.core.io.CharacterEscapes;
import com.fasterxml.jackson.core.util.VersionUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for JsonGenerator.writeEmbeddedObject.
 */
public class JsonGenerator_writeEmbeddedObject_TriageGen1Test {

    private JsonGenerator generator;

    @Before
    public void setUp() {
        // Since JsonGenerator is abstract, we use Mockito to create a mock instance
        generator = Mockito.mock(JsonGenerator.class);
    }

    /**
     * Tests the success path when the object is a byte array.
     * This covers the 'if (object instanceof byte[])' branch.
     */
    @Test
    public void testWriteEmbeddedObject_WithByteArray() throws IOException {
        byte[] data = new byte[]{0x01, 0x02, 0x03};

        generator.writeEmbeddedObject(data);

        // Verify that writeBinary was called with the correct byte array
        verify(generator, times(1)).writeBinary(data);
    }

    /**
     * Tests the error path when the object is not a byte array.
     * This covers the final throw statement in the method.
     */
    @Test(expected = JsonGenerationException.class)
    public void testWriteEmbeddedObject_WithUnsupportedType() throws IOException {
        Object unsupportedObject = "This is a string, not a byte array";

        // This should throw JsonGenerationException because String is not byte[]
        generator.writeEmbeddedObject(unsupportedObject);
    }

    /**
     * Tests the error path for null input.
     * Note: The provided code does not explicitly check for null before the instanceof check.
     * In Java, (null instanceof byte[]) is false, so it will fall through to the exception.
     */
    @Test(expected = JsonGenerationException.class)
    public void testWriteEmbeddedObject_WithNull() throws IOException {
        generator.writeEmbeddedObject(null);
    }

    /**
     * Tests the error path for other object types like Integer.
     */
    @Test(expected = JsonGenerationException.class)
    public void testWriteEmbeddedObject_WithInteger() throws IOException {
        generator.writeEmbeddedObject(123);
    }
}
